<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">def manage_account(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: str, user_id: str, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kwargs):</span></span>
